let db=load(); let query=''; let selectedPatient=db.patients[0]?.id;
function load(){try{const x=JSON.parse(localStorage.getItem(VERSION));return hydrateTenantDemoData(x||clone(seed))}catch{return hydrateTenantDemoData(clone(seed))}}
function save(){localStorage.setItem(VERSION,JSON.stringify(db))}
function uid(p){return p+'-'+Math.random().toString(36).slice(2,8).toUpperCase()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(v){return '₹'+Number(v||0).toLocaleString('en-IN')}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');clearTimeout(window.__t);window.__t=setTimeout(()=>e.classList.remove('show'),2200)}
function scoped(k){return (db[k]||[]).filter(x=>{if(x.organizationId&&x.organizationId!==db.context.organizationId)return false;if(db.context.clinicId&&x.clinicId&&x.clinicId!==db.context.clinicId)return false;if(db.context.role==='PATIENT'){const membership=db.memberships.find(m=>m.organizationId===db.context.organizationId&&m.role==='PATIENT'&&m.patientId);if(membership&&k==='patients'&&x.id!==membership.patientId)return false;if(membership&&x.patientId&&x.patientId!==membership.patientId)return false}return true})}
function can(permission){const permissions=ROLE_PERMISSIONS[db.context.role]||[];return permissions.includes('*')||permissions.includes(permission)}
function allowedModule(id){const permission=MODULE_PERMISSION[id];return !permission||can(permission)}
function guard(permission){if(can(permission))return true;toast(`Permission denied for ${db.context.role}`);return false}
function activeOrg(){return db.organizations.find(x=>x.id===db.context.organizationId)||db.organizations[0]}
function activeClinic(){return db.clinics.find(x=>x.id===db.context.clinicId&&x.organizationId===db.context.organizationId)}
function patientDashboard(){const patientId=db.memberships.find(x=>x.organizationId===db.context.organizationId&&x.role==='PATIENT'&&x.patientId)?.patientId;const p=scoped('patients').find(x=>x.id===patientId)||{};const appointments=scoped('appointments'),orders=scoped('orders'),followUps=scoped('followUps');return shell('My ClinicCare','Your appointments, care plan, documents and orders',`<div class="grid g4">${metric('Upcoming visits',appointments.filter(x=>x.status!=='COMPLETED'&&x.status!=='CANCELLED').length,'Your care journey')}${metric('Treatment sessions',scoped('treatments').reduce((s,x)=>s+(x.completed||0),0),'Completed sessions')}${metric('Open follow-ups',followUps.filter(x=>x.status!=='DONE').length,'Care team actions')}${metric('Orders',orders.length,'Your purchases')}</div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>Next appointments</h3>${table(['Date','Type','Status'],appointments.slice(0,5).map(x=>`<tr><td>${esc(x.date)} ${esc(x.time)}</td><td>${esc(x.type)}</td><td>${badge(x.status)}</td></tr>`))}</div><div class="card"><h3>Care timeline</h3><div class="list">${scoped('prescriptions').map(x=>`<div class="item">Prescription ${esc(x.id)} ${badge(x.status)}</div>`).join('')}${scoped('labs').map(x=>`<div class="item">${esc(x.test)} result ${badge(x.status)}</div>`).join('')||'<div class="muted">No recent care updates.</div>'}</div></div></div><div class="notice" style="margin-top:14px">Signed in as ${esc(p.name||'Patient')}. Financial, administrative, tenant, inventory and leadership data are not part of the patient view.</div>`)}
function patient(id){return db.patients.find(x=>x.id===id)||{name:'Unknown Patient'}}
function doctor(id){return db.doctors.find(x=>x.id===id)||{name:'Unassigned'}}
function badge(v){const good=['PAID','CAPTURED','COMPLETED','REVIEWED','ACTIVE','PUBLISHED','SIGNED','FULFILLED','AVAILABLE'];const warn=['PENDING','WAITING','NEW','OPEN','PARTIAL','DUE','IN_CONSULTATION'];const danger=['CANCELLED','ARCHIVED','SUSPENDED'];return `<span class="badge ${good.includes(v)?'good':warn.includes(v)?'warn':danger.includes(v)?'danger':'info'}">${esc(v)}</span>`}
function table(h,rows){return `<div class="tablewrap"><table class="table"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${h.length}" class="muted">No records in this context.</td></tr>`}</tbody></table></div>`}
function metric(label,value,note){return `<div class="card metric"><div class="label">${label}</div><div class="value">${value}</div><div class="trend">${note||''}</div></div>`}
function shell(title,sub,body,actions=''){return `<div class="h1">${title}</div><div class="sub">${sub}</div><div class="actions"><button class="btn" data-history-back>← Back</button>${actions}</div>${body}`}
function formModal(title,fields,submit){openModal(`<h2>${title}</h2><form id="modal-form"><div class="formgrid">${fields.join('')}</div><div class="actions"><button class="btn primary">${submit||'Save'}</button><button type="button" class="btn" data-close>Cancel</button></div></form>`);document.getElementById('modal-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());closeModal();return submitAction(title,d)}}
function field(label,name,value='',type='text',span=false){return `<div class="field ${span?'span2':''}"><label>${label}</label><input name="${name}" value="${esc(value)}" type="${type}" required></div>`}
function selectField(label,name,items,value='',span=false){return `<div class="field ${span?'span2':''}"><label>${label}</label><select name="${name}">${items.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)==value?'selected':''}>${esc(x.label??x)}</option>`).join('')}</select></div>`}
function openModal(html){document.getElementById('modalbox').innerHTML=html;document.getElementById('modal').classList.add('show')}
function closeModal(){document.getElementById('modal').classList.remove('show');document.getElementById('modalbox').innerHTML=''}
function mutate(action,entity,fn,key){key=key||action+'|'+uid('OP');if(db.idempotencyRecords.some(x=>x.key===key)){toast('Duplicate request safely ignored');return}fn();db.idempotencyRecords.unshift({id:uid('IDEM'),organizationId:db.context.organizationId,key,action,status:'COMPLETED',createdAt:new Date().toISOString()});db.auditLogs.unshift({id:uid('AUD'),organizationId:db.context.organizationId,entity,action,at:new Date().toISOString(),actor:db.context.role,clinicId:db.context.clinicId});save();toast('Saved — audited and duplicate-safe');render()}
function submitAction(title,d){
 if(title==='Add Category')return mutate('category.create','ProductServiceCategory',()=>db.categories.push({id:uid('CAT'),organizationId:db.context.organizationId,name:d.name,type:d.type,status:'ACTIVE'}));
 if(title==='Register Patient')return mutate('patient.create','Patient',()=>db.patients.push({id:uid('P'),organizationId:db.context.organizationId,clinicId:db.context.clinicId,name:d.name,phone:d.phone,dob:d.dob,gender:d.gender,status:'ACTIVE',lifetimeValue:0,source:d.source}));
 if(title==='New Lead')return mutate('lead.create','Lead',()=>db.leads.push({id:uid('LEAD'),organizationId:db.context.organizationId,name:d.name,source:d.source,stage:'NEW',value:Number(d.value),nextAction:'Follow up'}));
 if(title==='New Appointment')return mutate('appointment.create','Appointment',()=>db.appointments.push({id:uid('A'),organizationId:db.context.organizationId,clinicId:db.context.clinicId,patientId:d.patientId,doctorId:d.doctorId,date:d.date,time:d.time,type:d.type,status:'CONFIRMED',amount:Number(d.amount)}));
 if(title==='Add Service')return mutate('service.create','Service',()=>db.services.push({id:uid('SVC'),organizationId:db.context.organizationId,name:d.name,category:d.category,price:Number(d.price),status:'ACTIVE'}));
 if(title==='Add Product')return mutate('product.create','Product',()=>db.products.push({id:uid('PR'),organizationId:db.context.organizationId,name:d.name,categoryId:d.categoryId,price:Number(d.price),stock:Number(d.stock),reorder:Number(d.reorder),status:'ACTIVE'}));
 if(title==='Create Invoice')return mutate('invoice.create','Invoice',()=>db.invoices.push({id:uid('INV'),organizationId:db.context.organizationId,patientId:d.patientId,amount:Number(d.amount),status:'PENDING',source:d.source}));
 if(title==='Add Doctor')return mutate('doctor.create','Doctor',()=>db.doctors.push({id:uid('D'),organizationId:db.context.organizationId,name:d.name,specialty:d.specialty,status:'ACTIVE'}));
 if(title==='Add Follow-up')return mutate('followup.create','FollowUp',()=>db.followUps.push({id:uid('FU'),organizationId:db.context.organizationId,patientId:d.patientId,due:d.due,type:d.type,status:'OPEN'}));
 if(title==='New CMS Page')return mutate('cms.create','CMSPage',()=>db.cmsPages.push({id:uid('CMS'),organizationId:db.context.organizationId,slug:d.slug,title:d.title,status:'DRAFT'}));
 toast('Demo action completed');
}
function dashboard(){const p=scoped('patients'),a=scoped('appointments'),i=scoped('invoices'),paid=i.filter(x=>x.status==='PAID').reduce((s,x)=>s+x.amount,0),out=i.filter(x=>x.status!=='PAID').reduce((s,x)=>s+x.amount,0);return `<div class="hero"><h2>ClinicCare — Hospital Command Centre</h2><p>One operational system connecting patient acquisition, appointments, clinical care, diagnostics, therapy, products, billing, collections, staff and governance. Built to demonstrate measurable financial and operational outcomes to hospital leadership.</p><div class="actions"><button class="btn" data-go="value">Show hospital value</button><button class="btn" data-go="patients">Open patient journey</button><button class="btn" data-go="schema">Show API/schema alignment</button></div></div><div class="grid g4" style="margin-top:14px">${metric('Active patients',p.length,'Single longitudinal context')}${metric("Today's appointments",a.length,a.filter(x=>x.status==='WAITING').length+' waiting')}${metric('Collected revenue',money(paid),'Invoice/payment ledger')}${metric('Outstanding',money(out),'Collection opportunity')}</div><div class="grid g3" style="margin-top:14px"><div class="card"><h3>Revenue leakage radar</h3><div class="list"><div class="item">Pending invoices <b>${money(out)}</b> <span class="badge warn">COLLECT</span></div><div class="item">Open follow-ups <b>${scoped('followUps').filter(x=>x.status!=='DONE').length}</b> <span class="badge warn">RETAIN</span></div><div class="item">Low-stock products <b>${scoped('products').filter(x=>x.stock<x.reorder).length}</b> <span class="badge danger">CONTROL</span></div></div></div><div class="card"><h3>Patient conversion funnel</h3><div class="funnel"><div style="height:100%">Leads<br><b>${scoped('leads').length}</b></div><div style="height:82%">Booked<br><b>${a.length}</b></div><div style="height:66%">Visited<br><b>${scoped('consultations').length+2}</b></div><div style="height:52%">Repeat<br><b>${p.filter(x=>x.lifetimeValue>15000).length}</b></div></div></div><div class="card"><h3>Executive signals</h3><div class="list"><div class="item">Doctor capacity visibility <span class="badge good">LIVE</span></div><div class="item">Collection pipeline <span class="badge good">VISIBLE</span></div><div class="item">Audit + idempotency <span class="badge good">CONTROLLED</span></div><div class="item">Tenant isolation <span class="badge good">SCOPED</span></div></div></div></div>`}
function value(){const i=scoped('invoices'),out=i.filter(x=>x.status!=='PAID').reduce((s,x)=>s+x.amount,0),lead=scoped('leads').reduce((s,x)=>s+x.value,0),low=scoped('products').filter(x=>x.stock<x.reorder).length;const monthly=125000,leakage=out+lead*.08,inventory=low*1800,capacity=42000,benefit=leakage+inventory+capacity;return shell('Hospital Value & ROI','A proposal view designed for CFO / COO / Medical Director conversations',`<div class="grid g4">${metric('Illustrative monthly revenue opportunity',money(leakage),'Collections + conversion')}${metric('Inventory control opportunity',money(inventory),'Illustrative stock-risk value')}${metric('Capacity opportunity',money(capacity),'Illustrative utilization gain')}${metric('Combined opportunity',money(benefit),'Demo scenario — not a forecast')}</div><div class="grid g2" style="margin-top:14px"><div class="card roi"><h3>Why leadership cares</h3><p class="muted">ClinicCare turns operational events into measurable management signals: missed appointments, uncollected invoices, under-used doctor capacity, stalled follow-ups and stock risk become visible and actionable.</p><div class="actions"><button class="btn" data-go="reports">Open management reports</button><button class="btn" data-go="billing">Show collections</button></div></div><div class="card"><h3>Value levers</h3><div class="list"><div class="item"><b>Revenue capture</b><br><span class="muted">Invoice → payment → follow-up → reconciliation</span></div><div class="item"><b>Capacity</b><br><span class="muted">Doctor schedules → queue → utilization</span></div><div class="item"><b>Retention</b><br><span class="muted">Lead → visit → treatment → follow-up → review</span></div><div class="item"><b>Cost control</b><br><span class="muted">Inventory → reorder → product movement</span></div></div></div></div><div class="card" style="margin-top:14px"><h3>Proposal note</h3><p class="muted">Figures on this screen are intentionally illustrative for client discussion. Production ROI should be calculated from the hospital's own baseline KPIs, transaction volumes, collection ratios, utilization and inventory data.</p></div>`)}
