function monthly(){const monthKey=x=>String(x.date||x.createdAt||x.appointmentDate||'2026-09').slice(0,7)||'2026-09';const keys=[...new Set([...scoped('appointments'),...scoped('invoices'),...scoped('patients'),...scoped('orders')].map(monthKey))].sort().reverse();const rows=keys.map(month=>{const appointments=scoped('appointments').filter(x=>monthKey(x)===month),invoices=scoped('invoices').filter(x=>monthKey(x)===month),patients=scoped('patients').filter(x=>monthKey(x)===month),orders=scoped('orders').filter(x=>monthKey(x)===month),payments=scoped('payments').filter(x=>monthKey(x)===month),refunds=scoped('refunds').filter(x=>monthKey(x)===month);const invoiced=invoices.reduce((s,x)=>s+Number(x.amount||0),0),collected=payments.reduce((s,x)=>s+Number(x.amount||0),0)||invoices.filter(x=>x.status==='PAID').reduce((s,x)=>s+Number(x.amount||0),0),refunded=refunds.reduce((s,x)=>s+Number(x.amount||0),0);return `<tr><td><b>${month}</b></td><td>${appointments.length}</td><td>${patients.length}</td><td>${orders.length}</td><td>${money(invoiced)}</td><td>${money(collected)}</td><td>${money(Math.max(0,invoiced-collected-refunded))}</td><td>${money(refunded)}</td></tr>`});return shell('Monthly Totals','Tenant and clinic-scoped operational and financial totals',`<div class="notice">Totals are calculated from the active organization and clinic context. Patient accounts do not have access to this report.</div><div class="card" style="margin-top:14px">${table(['Month','Appointments','New patients','Orders','Invoiced','Collected','Outstanding','Refunded'],rows)}</div>`)}
function searchResults(q){if(!q)return '<span class="muted">Type to search the active tenant.</span>';const n=q.toLowerCase(),r=[];scoped('patients').forEach(x=>{if((x.name+x.id+x.phone).toLowerCase().includes(n))r.push(`<div class="item"><b>Patient</b> ${esc(x.name)} <button class="btn" data-patient="${x.id}">Open</button></div>`)});scoped('doctors').forEach(x=>{if((x.name+x.specialty).toLowerCase().includes(n))r.push(`<div class="item"><b>Doctor</b> ${esc(x.name)} — ${esc(x.specialty)}</div>`)});scoped('products').forEach(x=>{if((x.name+x.id).toLowerCase().includes(n))r.push(`<div class="item"><b>Product</b> ${esc(x.name)} — ${money(x.price)}</div>`)});return r.join('')||'<span class="muted">No matches.</span>'}
function audit(){return shell('Audit & Reliability','Traceability and duplicate-safe state changes',`<div class="grid g2"><div class="card"><h3>Audit trail</h3>${table(['When','Entity','Action'],db.auditLogs.filter(x=>x.organizationId===db.context.organizationId).slice(0,20).map(x=>`<tr><td>${new Date(x.at).toLocaleString()}</td><td>${esc(x.entity)}</td><td>${esc(x.action)}</td></tr>`))}</div><div class="card"><h3>Idempotency</h3><p class="muted">State-changing operations are represented with tenant-scoped operation keys. Repeated clicks/retries return the existing result instead of creating a duplicate business record.</p>${table(['Key','Action','Status'],db.idempotencyRecords.filter(x=>x.organizationId===db.context.organizationId).slice(0,12).map(x=>`<tr><td class="small">${esc(x.key)}</td><td>${esc(x.action)}</td><td>${badge(x.status)}</td></tr>`))}</div></div>`)}
function schema(){const groups=Object.entries(CLINICCARE_SCHEMA);const count=groups.reduce((n,[,v])=>n+v.length,0);return shell('API / Schema Map','UI modules are driven by a centralized domain contract instead of ad-hoc screen-only state',`<div class="notice"><b>Alignment principle:</b> the demo separates navigation, domain metadata, state and UI rendering. When the exact Prisma schema changes, the schema adapter can be updated without rewriting every screen. The uploaded TDD documents 55 Prisma models and 13 enums; the approval pack does not include the literal schema.prisma, so this map uses the documented domain vocabulary rather than inventing undisclosed model names.</div><div class="grid g4" style="margin-top:14px">${metric('Documented model mappings',count,'Central manifest')}${metric('API controller domains','24','Per TDD')}${metric('Tenant boundary','Organization','DB-authoritative')}${metric('Scope headers','X-Tenant-Slug + X-Clinic-Id','Request context')}</div><div class="grid g3" style="margin-top:14px">${groups.map(([g,items])=>`<div class="card schema-card"><h3>${g.toUpperCase()}</h3>${items.map(x=>`<div class="item" style="margin-bottom:7px"><b>${x.label}</b><br><span class="small muted">${x.domain} • ${x.scope}</span><br><span class="small">↳ ${x.relations.join(', ')||'—'}</span></div>`).join('')}</div>`).join('')}</div>`)}
function settings(){const o=activeOrg(),c=activeClinic();return shell('Tenant & Environment','Demonstrate controlled deployment context and tenant/clinic isolation',`<div class="grid g3">${metric('Environment',db.context.environment,'Independent deployment data')}${metric('Organization',o?.name||'—','Tenant boundary')}${metric('Clinic',c?.name||'Organization-wide','Narrowed request scope')}</div><div class="card" style="margin-top:14px"><h3>Production architecture message</h3><ul><li>Development, staging and production have independent databases, Redis, secrets, storage and runtime namespaces.</li><li>Organization is the tenant boundary; clinic is an optional narrower scope.</li><li>Protected requests revalidate account, membership, tenant lifecycle, clinic and role state.</li><li>JWT permissions are transport hints; database RBAC is authoritative.</li></ul><button class="btn danger" data-action="reset">Reset proposal demo data</button></div>`)}

